규칙:
- query source는 위 목록에서 정확히 하나만 선택합니다.
- source_alias와 column은 제공된 실제 문자열을 그대로 사용합니다.
- 전역 데이터셋, Table Catalog, Main Filter, 표준 컬럼명 또는 새 컬럼명을 만들지 않습니다.
- 외부 조회, join, groupby, 계산식, 자유 pandas/Python 코드는 만들지 않습니다.
- 허용 operation은 filter, sort, top_n, select뿐입니다.
- materialized view의 predicates는 이미 적용된 조건이므로 중복 filter로 만들지 않습니다.
- 직전 결과 이어가기가 true이면 직전 계획은 서버가 합성하므로 이번 질문에서 새로 요구한 차이 연산만 반환합니다.
- null 정렬은 항상 last입니다.
- 질문에서 요구하지 않은 filter, sort, limit을 추가하지 않습니다.
- 처리할 수 없으면 status=clarification_required와 reason을 반환합니다.

다음 JSON object 하나만 반환합니다.
{{
  "status": "ready | clarification_required",
  "source_alias": "선택한 source_alias",
  "operations": [
    {{"operation": "filter", "conditions": [{{"column": "실제 컬럼", "operator": "eq", "value": "질문에 명시된 값"}}]}},
    {{"operation": "sort", "column": "실제 컬럼", "direction": "asc | desc", "nulls": "last"}},
    {{"operation": "top_n", "limit": 5}},
    {{"operation": "select", "columns": ["실제 컬럼"]}}
  ],
  "reason": "짧은 판단 근거"
}}
"""


# 함수 설명: 입력 값을 공백이 제거된 문자열로 정규화합니다.
def _text(value: Any) -> str:
    return "" if value is None else str(value).strip()


# 함수 설명: Langflow Data 또는 dict에서 안전한 payload 사본을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    raw = getattr(value, "data", value)
    return deepcopy(raw) if isinstance(raw, dict) else {}


# 함수 설명: Message와 문자열 입력에서 길이가 제한된 사용자 질문을 추출합니다.
def _question(value: Any) -> str:
    data = getattr(value, "data", None)
    data = data if isinstance(data, dict) else {}
    text = _text(getattr(value, "text", None) or data.get("text") or data.get("question"))
    if not text and isinstance(value, str):
        text = value.strip()
    return text[:MAX_QUESTION_CHARS]


# 함수 설명: Session Loader 출력에서 상태와 로드 상태를 분리합니다.
def _state(value: Any) -> tuple[dict[str, Any], dict[str, Any]]:
    payload = _payload(value)
    state = payload.get("state") if isinstance(payload.get("state"), dict) else payload
    load_status = payload.get("session_state_load") if isinstance(payload.get("session_state_load"), dict) else {}
    return deepcopy(state) if isinstance(state, dict) else {}, deepcopy(load_status)


# 함수 설명: 호환 가능한 상태 키에서 세션 식별자를 찾습니다.
def _session_id(state: dict[str, Any]) -> str:
    for key in ("session_id", "conversation_id", "chat_id", "thread_id"):
        if _text(state.get(key)):
            return _text(state.get(key))
    request = state.get("request") if isinstance(state.get("request"), dict) else {}
    return _text(request.get("session_id"))


# 함수 설명: 세션 상태의 낙관적 잠금 revision을 검증해 반환합니다.
def _session_revision(state: dict[str, Any]) -> int | None:
    value = state.get("_session_state_revision")
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return parsed if parsed >= 0 else None


# 함수 설명: 중복과 빈 값을 제거한 제한 길이 문자열 목록을 만듭니다.
def _string_list(value: Any, limit: int = MAX_COLUMNS_PER_SOURCE) -> list[str]:
    result: list[str] = []
    for item in value if isinstance(value, list) else []:
        text = _text(item)
        if text and text not in result:
            result.append(text)
        if len(result) >= limit:
            break
    return result


# 함수 설명: View 별칭 비교에 사용할 정규화 문구를 만듭니다.
def _normalized_phrase(value: Any) -> str:
    return re.sub(r"[\s_-]+", "", _text(value)).casefold()


# 함수 설명: 스냅샷 범위를 벗어나는 최신 조회 또는 교차 원천 요청을 탐지합니다.
def _requires_live_retrieval(question: str) -> bool:
    """Detect explicit refresh/cross-source requests without matching column names.

    In particular, ``현재작업재공`` is a physical snapshot column and must not
    be mistaken for the standalone freshness cue ``현재``.
    """

    lowered = question.casefold()
    if any(phrase.casefold() in lowered for phrase in (*FRESH_DATA_PHRASES, *CROSS_SOURCE_PHRASES)):
        return True
    standalone = re.compile(r"(?<![0-9A-Za-z가-힣_])(현재|지금|최신)(?![0-9A-Za-z가-힣_])", re.IGNORECASE)
    return bool(standalone.search(question))


# 함수 설명: 레거시 source alias에 대응하는 기본 Report 용도를 결정합니다.
def _default_purpose(alias: str) -> str:
    lowered = alias.casefold()
    if "shortage" in lowered and "product" in lowered:
        return "production_shortage_products"
    return "case_detail" if alias == "report_snapshot" else alias


# 함수 설명: Report 계약의 허용 연산 이름을 제한형 연산 집합으로 정규화합니다.
def _normalized_allowed_operations(value: Any, fallback: Any = None) -> list[str]:
    aliases = {
        "apply_filters": "filter",
        "sort_and_top_n": "sort",
        "sort": "sort",
        "top_n": "top_n",
        "select_columns": "select",
        "select": "select",
        "filter": "filter",
    }
    result: list[str] = []
    raw = value if isinstance(value, list) and value else fallback
    for item in raw if isinstance(raw, list) else []:
        normalized = aliases.get(_text(item).casefold())
        if normalized and normalized not in result:
            result.append(normalized)
        if _text(item).casefold() == "sort_and_top_n" and "top_n" not in result:
            result.append("top_n")
    if "select" not in result:
        result.append("select")
    return result


# 함수 설명: 저장된 Report 상태에서 후속 조회용 query source 계약만 추출합니다.
def _query_source_contracts(state: dict[str, Any]) -> list[dict[str, Any]]:
    current_data = state.get("current_data") if isinstance(state.get("current_data"), dict) else {}
    context = current_data.get("report_context") if isinstance(current_data.get("report_context"), dict) else {}
    candidates = context.get("query_sources") if isinstance(context.get("query_sources"), list) else []
    if not candidates and isinstance(current_data.get("query_sources"), list):
        candidates = current_data["query_sources"]
    source_columns = current_data.get("source_columns_by_alias") if isinstance(current_data.get("source_columns_by_alias"), dict) else {}
    dataset_keys = _string_list(current_data.get("source_dataset_keys"), MAX_QUERY_SOURCES)
    aliases_in_state = _string_list(current_data.get("source_aliases"), MAX_QUERY_SOURCES)
    fallback_allowed = context.get("allowed_operations")
    normalized: list[dict[str, Any]] = []

    for raw_item in candidates[:MAX_QUERY_SOURCES]:
        if not isinstance(raw_item, dict):
            continue
        raw = raw_item.get("query_source_contract") if isinstance(raw_item.get("query_source_contract"), dict) else raw_item
        alias = _text(raw.get("source_alias"))
        if not alias or not SAFE_SOURCE_ALIAS.fullmatch(alias):
            continue
        purpose = _text(raw.get("purpose")) or _default_purpose(alias)
        columns = _string_list(raw.get("columns")) or _string_list(source_columns.get(alias))
        grain = raw.get("grain") if isinstance(raw.get("grain"), dict) else {}
        display_name = _text(raw.get("display_name")) or purpose or alias
        known_aliases = [display_name, *KNOWN_VIEW_ALIASES.get(purpose, []), *_string_list(raw.get("aliases"), 30)]
        contract = {
            "contract_version": _text(raw.get("contract_version")) or QUERY_SOURCE_CONTRACT_VERSION,
            "source_alias": alias,
            "dataset_key": _text(raw.get("dataset_key")) or alias,
            "purpose": purpose,
            "display_name": display_name,
            "aliases": list(dict.fromkeys(known_aliases)),
            "authoritative": raw.get("authoritative") is True,
            "columns": columns,
            "grain": {
                "kind": _text(grain.get("kind")) or "detail",
                "columns": _string_list(grain.get("columns")),
            },
            "metrics": [deepcopy(item) for item in raw.get("metrics", []) if isinstance(item, dict)][:50],
            "predicates": [deepcopy(item) for item in raw.get("predicates", []) if isinstance(item, dict)][:50],
            "allowed_operations": _normalized_allowed_operations(raw.get("allowed_operations"), fallback_allowed),
            "default_display_columns": _string_list(raw.get("default_display_columns")),
            "default_view": raw.get("default_view") is True,
            "lineage": _string_list(raw.get("lineage"), MAX_QUERY_SOURCES),
        }
        if contract["contract_version"] == QUERY_SOURCE_CONTRACT_VERSION and columns:
            normalized.append(contract)

    # Additive compatibility for Report contexts created before query_sources existed.
    if not normalized:
        for index, alias in enumerate(aliases_in_state):
            columns = _string_list(source_columns.get(alias))
            if not columns:
                continue
            normalized.append(
                {
                    "contract_version": QUERY_SOURCE_CONTRACT_VERSION,
                    "source_alias": alias,
                    "dataset_key": dataset_keys[index] if index < len(dataset_keys) else alias,
                    "purpose": _default_purpose(alias),
                    "aliases": KNOWN_VIEW_ALIASES.get(_default_purpose(alias), []),
                    # Legacy fallback is visible to the planner but is not authoritative;
                    # the executor will fail closed until the stored source declares its contract.
                    "authoritative": False,
                    "columns": columns,
                    "grain": {"kind": "detail", "columns": []},
                    "metrics": [],
                    "predicates": [],
                    "allowed_operations": _normalized_allowed_operations(fallback_allowed),
                    "default_display_columns": [],
                }
            )
    return normalized[:MAX_QUERY_SOURCES]


# 함수 설명: 질문에 명시된 Report View 별칭과 가장 잘 맞는 source만 반환합니다.
def _explicit_source_matches(question: str, sources: list[dict[str, Any]]) -> list[dict[str, Any]]:
    normalized_question = _normalized_phrase(question)
    scored: list[tuple[int, dict[str, Any]]] = []
    for source in sources:
        terms = [source.get("display_name"), source.get("purpose"), source.get("source_alias"), *source.get("aliases", [])]
        matches = [len(_normalized_phrase(term)) for term in terms if _normalized_phrase(term) and _normalized_phrase(term) in normalized_question]
        if matches:
            scored.append((max(matches), source))
    if scored:
        best = max(score for score, _ in scored)
        return [source for score, source in scored if score == best]
    return []


# 함수 설명: 질문이 Report 전체가 아니라 직전 결과 subset을 가리키는지 판정합니다.
def _continues_previous_result(question: str) -> bool:
    lowered = question.casefold()
    return any(marker.casefold() in lowered for marker in RESULT_CONTINUATION_MARKERS)


# 함수 설명: 명시 별칭, 직전 결과 참조, Report 원본 순서로 source 후보를 좁힙니다.
def _matched_sources(question: str, sources: list[dict[str, Any]], current_view_plan: dict[str, Any]) -> list[dict[str, Any]]:
    explicit = _explicit_source_matches(question, sources)
    if explicit:
        return explicit

    previous_alias = _text(current_view_plan.get("source_alias"))
    if previous_alias and _continues_previous_result(question):
        previous = [source for source in sources if source.get("source_alias") == previous_alias]
        if previous:
            return previous
    defaults = [source for source in sources if source.get("default_view") is True]
    if len(defaults) == 1:
        return defaults
    defaults = [source for source in sources if source.get("purpose") == "case_detail"]
    if len(defaults) == 1:
        return defaults
    return sources if len(sources) == 1 else []


# 함수 설명: 상태에서 직전 Report 후속 View 계획을 복원합니다.
def _current_view_plan(state: dict[str, Any]) -> dict[str, Any]:
    current_data = state.get("current_data") if isinstance(state.get("current_data"), dict) else {}
    if isinstance(current_data.get("current_view_plan"), dict):
        return deepcopy(current_data["current_view_plan"])
    if isinstance(state.get("current_view_plan"), dict):
        return deepcopy(state["current_view_plan"])
    last_plan = state.get("last_intent_plan") if isinstance(state.get("last_intent_plan"), dict) else {}
    return deepcopy(last_plan.get("report_execution_plan")) if isinstance(last_plan.get("report_execution_plan"), dict) else {}


# 함수 설명: 일관된 오류 항목을 생성합니다.
def _error(issue_type: str, message: str) -> dict[str, str]:
    return {"type": issue_type, "message": message}


# 주요 함수: 질문과 세션 상태를 검증하고 Report 후속 요청 계약을 생성합니다.
def build_report_followup_request(question_value: Any, loaded_state_value: Any) -> dict[str, Any]:
    question = _question(question_value)
    state, load_status = _state(loaded_state_value)
    current_data = state.get("current_data") if isinstance(state.get("current_data"), dict) else {}
    report_context = current_data.get("report_context") if isinstance(current_data.get("report_context"), dict) else {}
    query_sources = _query_source_contracts(state)
    current_plan = _current_view_plan(state)
    session_id = _session_id(state)
    session_revision = _session_revision(state)
    errors: list[dict[str, str]] = []
    status = "ready"

    if not question:
        errors.append(_error("empty_report_followup_question", "Report 후속 질문이 비어 있습니다."))
        status = "blocked"
    elif not session_id:
        errors.append(_error("report_followup_session_missing", "현재 실행의 session_id를 확인할 수 없습니다."))
        status = "blocked"
    elif session_revision is None:
        errors.append(_error("report_session_revision_missing", "Report 후속 분석의 세션 revision을 확인할 수 없어 상태 경합 보호를 적용할 수 없습니다."))
        status = "blocked"
    elif not (_text(report_context.get("context_ref")) and _text(report_context.get("report_type"))):
        errors.append(_error("report_context_missing", "같은 세션에서 재사용 가능한 Report Context를 찾을 수 없습니다."))
        status = "blocked"
    elif not query_sources:
        errors.append(_error("report_query_sources_missing", "Report가 후속 조회용 query source를 선언하지 않았습니다."))
        status = "blocked"
    elif _requires_live_retrieval(question):
        status = "handoff_required"
        errors.append(_error("live_retrieval_required", "현재·최신 또는 다른 원천 데이터 요청은 일반 데이터 분석 Flow의 신규 조회가 필요합니다."))

    matched = _matched_sources(question, query_sources, current_plan) if status == "ready" else []
    explicit_matches = _explicit_source_matches(question, query_sources) if status == "ready" else []
    inherit_current_view = bool(
        status == "ready"
        and not explicit_matches
        and _continues_previous_result(question)
        and len(matched) == 1
        and _text(current_plan.get("source_alias")) == _text(matched[0].get("source_alias"))
    )
    if status == "ready" and not matched:
        status = "clarification_required"
        errors.append(_error("report_query_source_ambiguous", "질문에 사용할 Report View를 하나로 확정할 수 없습니다."))

    request = {
        "contract_version": REQUEST_CONTRACT_VERSION,
        "request": {
            "question": question,
            "session_id": session_id,
            "reference_date": datetime.now(timezone(timedelta(hours=9))).strftime("%Y%m%d"),
        },
        "state": state,
        # 공용 Result Loader가 일반 data_ref보다 Report context_ref를 우선하고
        # Report 전용 TTL/완전성 검증을 적용하도록 명시합니다.
        "followup_hint": {
            "report_reference": bool(_text(report_context.get("context_ref"))),
            "unresolved_report_reference": not bool(_text(report_context.get("context_ref"))),
            "fresh_data_requested": status == "handoff_required",
            "request_scope_hint": "followup_transform" if status == "ready" else status,
        },
        "report_followup": {
            "status": status,
            "report_anchor": {
                "context_version": _text(report_context.get("context_version")),
                "context_ref": _text(report_context.get("context_ref")),
                "report_type": _text(report_context.get("report_type")),
                "as_of": _text(report_context.get("as_of")),
                "expires_at": _text(report_context.get("expires_at")),
                "session_revision": session_revision,
            },
            "query_sources": query_sources,
            "candidate_source_aliases": [item["source_alias"] for item in matched],
            "inherit_current_view": inherit_current_view,
            "current_view_plan": current_plan,
        },
        "intent_plan": {},
        "source_results": [],
        "runtime_sources": {},
        "analysis": {},
        "data": {},
        "execution_gate": {"status": "ready" if status == "ready" else status},
        "trace": {
            "warnings": [],
            "errors": errors,
            "inspection": {
                "report_followup_prompt": {
                    "stage": "00_report_followup_prompt_builder",
                    "status": status,
                    "session_state_loaded": load_status.get("loaded"),
                    "query_source_count": len(query_sources),
                    "candidate_source_aliases": [item["source_alias"] for item in matched],
                    "errors": deepcopy(errors),
                }
            },
        },
    }
    return request


# 주요 함수: 선택된 Report query source만 포함하는 제한형 계획 Prompt를 생성합니다.
def build_report_followup_prompt(payload_value: Any, prompt_template: Any = "") -> str:
    payload = _payload(payload_value)
    report_followup = payload.get("report_followup") if isinstance(payload.get("report_followup"), dict) else {}
    if report_followup.get("status") != "ready":
        return ""
    candidates = set(_string_list(report_followup.get("candidate_source_aliases"), MAX_QUERY_SOURCES))
    sources = [
        deepcopy(item)
        for item in report_followup.get("query_sources", [])
        if isinstance(item, dict) and (not candidates or item.get("source_alias") in candidates)
    ]
    compact_sources = []
    for item in sources:
        compact_sources.append(
            {
                "source_alias": item.get("source_alias"),
                "dataset_key": item.get("dataset_key"),
                "purpose": item.get("purpose"),
                "display_name": item.get("display_name"),
                "aliases": item.get("aliases", []),
                "columns": item.get("columns", []),
                "grain": item.get("grain", {}),
                "metrics": item.get("metrics", []),
                "predicates_already_applied": item.get("predicates", []),
                "allowed_operations": item.get("allowed_operations", []),
                "default_display_columns": item.get("default_display_columns", []),
                "default_view": item.get("default_view") is True,
                "lineage": item.get("lineage", []),
            }
        )
    template = _text(prompt_template) or DEFAULT_PROMPT_TEMPLATE
    return template.format(
        question=_text(payload.get("request", {}).get("question")),
        query_sources_json=json.dumps(compact_sources, ensure_ascii=False, separators=(",", ":"), default=str),
        current_view_plan_json=json.dumps(report_followup.get("current_view_plan", {}), ensure_ascii=False, separators=(",", ":"), default=str),
        inherit_current_view_json=json.dumps(bool(report_followup.get("inherit_current_view"))),
    )


# Langflow 컴포넌트 클래스: Report 후속 요청 payload와 계획 Prompt를 함께 출력합니다.
class ReportFollowupPromptBuilder(Component):
    display_name = "00 Report 후속 질문 Prompt 생성기"
    description = "Report가 선언한 materialized query source만 사용해 제한형 실행 계획 Prompt를 만듭니다."
    name = "ReportFollowupPromptBuilder"
    icon = "FileSearch"
    inputs = [
        HandleInput(name="question", display_name="사용자 질문", input_types=["Message"], required=True),
        DataInput(name="loaded_state", display_name="불러온 세션 상태", required=True),
        MultilineInput(name="prompt_template", display_name="Report 후속 계획 Prompt", value=DEFAULT_PROMPT_TEMPLATE, required=False, advanced=True),
    ]
    outputs = [
        Output(name="payload_out", display_name="요청 페이로드", method="build_payload", types=["Data"], group_outputs=True),
        Output(name="prompt", display_name="계획 Prompt", method="build_prompt", types=["Message"], group_outputs=True),
    ]

    # 주요 메서드: 동일 실행 내에서 요청 payload를 한 번만 생성해 재사용합니다.
    def _request_payload(self) -> dict[str, Any]:
        return build_report_followup_request(getattr(self, "question", None), getattr(self, "loaded_state", None))

    # Langflow 출력 함수: 정규화기로 전달할 요청 payload를 Data로 반환합니다.
    def build_payload(self) -> Data:
        result = self._request_payload()
        self.status = result.get("trace", {}).get("inspection", {}).get("report_followup_prompt", {})
        return Data(data=result)

    # Langflow 출력 함수: Language Model에 전달할 계획 Prompt Message를 반환합니다.
    def build_prompt(self) -> Message:
        prompt = build_report_followup_prompt(self._request_payload(), getattr(self, "prompt_template", ""))
        message = Message(text=prompt)
        self.status = message
        return message

# -*- coding: utf-8 -*-
# =============================================================================
# 컴포넌트 개요: 01 Report 후속 실행 계획 검증기
# 역할: Intent LLM JSON을 Report-local physical schema에 맞는 제한형 실행 계획으로 정규화합니다.
# 주요 입력: 00 요청 payload, Intent LLM 응답
# 주요 출력: 공용 MongoDB Result Loader와 전용 executor가 소비할 payload
# 처리 흐름: JSON 해석 -> source/column/value/operation 검증 -> previous_source 복원 계약 생성
# 유지보수 포인트: LLM이 만든 dataset·column·code를 허용하지 않으며 authoritative query source만 실행합니다.
# =============================================================================

from __future__ import annotations

import json
import re
from copy import deepcopy
from typing import Any

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, MessageTextInput, Output
from lfx.schema.data import Data


PLAN_CONTRACT_VERSION = "report.followup.plan.v1"
QUERY_SOURCE_CONTRACT_VERSION = "report.query_source.v1"
SUPPORTED_OPERATIONS = {"filter", "sort", "top_n", "select"}
SUPPORTED_FILTER_OPERATORS = {
    "eq",
    "ne",
    "in",
    "not_in",
    "contains",
    "starts_with",
    "ends_with",
    "gt",
    "ge",
    "lt",
    "le",
    "is_blank",
    "not_blank",
}
MAX_OPERATIONS = 16
MAX_CONDITIONS = 30
MAX_TOP_N = 100


# 함수 설명: 입력 값을 공백이 제거된 문자열로 정규화합니다.
def _text(value: Any) -> str:
    return "" if value is None else str(value).strip()


# 함수 설명: Langflow Data 또는 dict에서 안전한 payload 사본을 꺼냅니다.
def _payload(value: Any) -> dict[str, Any]:
    raw = getattr(value, "data", value)
    return deepcopy(raw) if isinstance(raw, dict) else {}


# 함수 설명: Language Model 응답에서 JSON 후보 문자열을 추출합니다.
def _response_text(value: Any) -> str:
    if isinstance(value, dict):
        return json.dumps(value, ensure_ascii=False)
    data = getattr(value, "data", None)
    if isinstance(data, dict):
        if isinstance(data.get("report_followup_plan"), dict):
            return json.dumps(data["report_followup_plan"], ensure_ascii=False)
        if isinstance(data.get("intent_plan"), dict):
            return json.dumps(data["intent_plan"], ensure_ascii=False)
        if _text(data.get("text")):
            return _text(data.get("text"))
    return _text(getattr(value, "text", None) or getattr(value, "content", None) or value)


# 함수 설명: 모델 응답을 단일 JSON object로 엄격하게 해석합니다.
def _parse_response(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        if isinstance(value.get("report_followup_plan"), dict):
            return deepcopy(value["report_followup_plan"])
        if isinstance(value.get("intent_plan"), dict):
            return deepcopy(value["intent_plan"])
        return deepcopy(value)
    text = _response_text(value)
    if not text:
        return {}
    text = re.sub(r"^\s*```(?:json)?\s*", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s*```\s*$", "", text)
    try:
        parsed = json.loads(text)
    except (TypeError, ValueError, json.JSONDecodeError):
        match = re.search(r"\{.*\}", text, flags=re.DOTALL)
        if not match:
            return {}
        try:
            parsed = json.loads(match.group(0))
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
    if isinstance(parsed, dict) and isinstance(parsed.get("report_followup_plan"), dict):
        return parsed["report_followup_plan"]
    return parsed if isinstance(parsed, dict) else {}


# 함수 설명: 요청 계약의 query source를 alias 기준 사전으로 구성합니다.
def _sources(payload: dict[str, Any]) -> dict[str, dict[str, Any]]:
    followup = payload.get("report_followup") if isinstance(payload.get("report_followup"), dict) else {}
    result: dict[str, dict[str, Any]] = {}
    for item in followup.get("query_sources", []) if isinstance(followup.get("query_sources"), list) else []:
        if not isinstance(item, dict):
            continue
        alias = _text(item.get("source_alias"))
        if alias:
            result[alias] = deepcopy(item)
    return result


# 함수 설명: 중복과 빈 값을 제거한 문자열 목록을 만듭니다.
def _string_list(value: Any) -> list[str]:
    result: list[str] = []
    for item in value if isinstance(value, list) else []:
        text = _text(item)
        if text and text not in result:
            result.append(text)
    return result


# 함수 설명: source 계약에서 제한형 실행기가 허용할 연산 집합을 구합니다.
def _allowed_operations(source: dict[str, Any]) -> set[str]:
    result: set[str] = {"select"}
    for value in source.get("allowed_operations", []) if isinstance(source.get("allowed_operations"), list) else []:
        item = _text(value).casefold()
        if item in SUPPORTED_OPERATIONS:
            result.add(item)
        elif item == "apply_filters":
            result.add("filter")
        elif item == "sort_and_top_n":
            result.update({"sort", "top_n"})
        elif item == "select_columns":
            result.add("select")
    return result


# 함수 설명: filter 값 출처 검증에 사용할 정규화된 질문을 반환합니다.
def _normalized_question(payload: dict[str, Any]) -> str:
    request = payload.get("request") if isinstance(payload.get("request"), dict) else {}
    return re.sub(r"[\s,_-]+", "", _text(request.get("question"))).casefold()


# 함수 설명: 요청한 조건이 Report가 선언한 고정 predicate와 일치하는지 확인합니다.
def _predicate_matches(source: dict[str, Any], column: str, operator: str, value: Any) -> bool:
    for item in source.get("predicates", []) if isinstance(source.get("predicates"), list) else []:
        if not isinstance(item, dict):
            continue
        if (
            _text(item.get("column")) == column
            and _text(item.get("operator")).casefold() == operator
            and item.get("value") == value
        ):
            return True
    return False


# 함수 설명: filter 값이 사용자 질문에 명시적으로 포함됐는지 확인합니다.
def _value_explicit_in_question(question: str, value: Any) -> bool:
    values = value if isinstance(value, list) else [value]
    if not values:
        return False
    for item in values:
        if item is None:
            return False
        normalized = re.sub(r"[\s,_-]+", "", _text(item)).casefold()
        if not normalized or normalized not in question:
            return False
    return True


# 함수 설명: 단일 filter 조건의 컬럼과 연산자와 값 출처를 검증합니다.
def _condition(
    raw: dict[str, Any],
    source: dict[str, Any],
    question: str,
    *,
    allow_persisted_value: bool = False,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    column = _text(raw.get("column") or raw.get("field"))
    operator = _text(raw.get("operator") or "eq").casefold()
    columns = set(_string_list(source.get("columns")))
    if column not in columns:
        return None, {
            "type": "report_followup_column_not_declared",
            "message": f"Report View에 선언되지 않은 filter 컬럼입니다: {column or '(empty)'}",
            "column": column,
        }
    if operator not in SUPPORTED_FILTER_OPERATORS:
        return None, {
            "type": "report_followup_filter_operator_not_allowed",
            "message": f"Report 후속 분석에서 허용하지 않는 filter operator입니다: {operator or '(empty)'}",
            "operator": operator,
        }
    value = deepcopy(raw.get("value"))
    if operator in {"is_blank", "not_blank"}:
        value = None
    elif not (allow_persisted_value or _predicate_matches(source, column, operator, value) or _value_explicit_in_question(question, value)):
        return None, {
            "type": "report_followup_filter_value_not_grounded",
            "message": f"질문 또는 Report 계약에서 근거를 확인할 수 없는 filter 값입니다: {column}",
            "column": column,
            "operator": operator,
        }
    return {"column": column, "operator": operator, "value": value}, None


# 함수 설명: 모델 연산 계획을 허용된 filter, sort, top_n, select 계약으로 정규화합니다.
def _normalize_operations(
    raw_operations: Any,
    source: dict[str, Any],
    question: str,
    *,
    allow_persisted_filter_values: bool = False,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    operations: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    allowed = _allowed_operations(source)
    columns = _string_list(source.get("columns"))
    column_set = set(columns)
    raw_items = raw_operations if isinstance(raw_operations, list) else []
    if len(raw_items) > MAX_OPERATIONS:
        return [], [{"type": "report_followup_operation_limit_exceeded", "message": f"Report 후속 operation은 최대 {MAX_OPERATIONS}개까지 허용합니다."}]

    for raw in raw_items:
        if not isinstance(raw, dict):
            errors.append({"type": "report_followup_operation_invalid", "message": "Report 후속 operation은 JSON object여야 합니다."})
            continue
        operation = _text(raw.get("operation") or raw.get("op")).casefold()
        operation_aliases = {"apply_filters": "filter", "sort_and_top_n": "sort", "select_columns": "select"}
        operation = operation_aliases.get(operation, operation)
        if operation not in SUPPORTED_OPERATIONS or operation not in allowed:
            errors.append(
                {
                    "type": "report_followup_operation_not_allowed",
                    "message": f"선택한 Report View에서 허용하지 않는 operation입니다: {operation or '(empty)'}",
                    "operation": operation,
                }
            )
            continue

        if operation == "filter":
            conditions_raw = raw.get("conditions") if isinstance(raw.get("conditions"), list) else [raw]
            if len(conditions_raw) > MAX_CONDITIONS:
                errors.append({"type": "report_followup_filter_limit_exceeded", "message": f"filter 조건은 최대 {MAX_CONDITIONS}개까지 허용합니다."})
                continue
            conditions: list[dict[str, Any]] = []
            for raw_condition in conditions_raw:
                if not isinstance(raw_condition, dict):
                    errors.append({"type": "report_followup_filter_invalid", "message": "filter condition은 JSON object여야 합니다."})
                    continue
                normalized, error = _condition(
                    raw_condition,
                    source,
                    question,
                    allow_persisted_value=allow_persisted_filter_values,
                )
                if error:
                    errors.append(error)
                elif normalized:
                    conditions.append(normalized)
            if conditions:
                operations.append({"operation": "filter", "conditions": conditions})
            continue

        if operation == "sort":
            column = _text(raw.get("column") or raw.get("sort_by"))
            direction = _text(raw.get("direction") or raw.get("order") or "asc").casefold()
            if column not in column_set:
                errors.append({"type": "report_followup_column_not_declared", "message": f"Report View에 선언되지 않은 sort 컬럼입니다: {column or '(empty)'}", "column": column})
                continue
            if direction not in {"asc", "desc"}:
                errors.append({"type": "report_followup_sort_direction_invalid", "message": f"sort direction은 asc/desc만 허용합니다: {direction}"})
                continue
            operations.append({"operation": "sort", "column": column, "direction": direction, "nulls": "last"})
            continue

        if operation == "top_n":
            try:
                limit = int(raw.get("limit"))
            except (TypeError, ValueError, OverflowError):
                limit = 0
            if not 1 <= limit <= MAX_TOP_N:
                errors.append({"type": "report_followup_top_n_invalid", "message": f"top_n limit은 1~{MAX_TOP_N} 범위여야 합니다."})
                continue
            operations.append({"operation": "top_n", "limit": limit})
            continue

        selected = _string_list(raw.get("columns"))
        missing = [column for column in selected if column not in column_set]
        if not selected or missing:
            errors.append(
                {
                    "type": "report_followup_select_columns_invalid",
                    "message": "select 컬럼은 선택한 Report View의 실제 컬럼만 사용할 수 있습니다.",
                    "missing_columns": missing,
                }
            )
            continue
        operations.append({"operation": "select", "columns": selected})

    return operations, errors


# 함수 설명: 직전 View 계획을 같은 source 계약에 다시 대조해 상속 가능한 연산만 복원합니다.
def _inherited_operations(
    payload: dict[str, Any],
    source: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], dict[str, Any]]:
    followup = payload.get("report_followup") if isinstance(payload.get("report_followup"), dict) else {}
    if followup.get("inherit_current_view") is not True:
        return [], [], {}
    previous = followup.get("current_view_plan") if isinstance(followup.get("current_view_plan"), dict) else {}
    source_alias = _text(source.get("source_alias"))
    dataset_key = _text(source.get("dataset_key") or source_alias)
    if (
        previous.get("contract_version") != PLAN_CONTRACT_VERSION
        or _text(previous.get("source_alias")) != source_alias
        or (_text(previous.get("dataset_key")) and _text(previous.get("dataset_key")) != dataset_key)
    ):
        return [], [
            {
                "type": "report_followup_previous_view_invalid",
                "message": "직전 결과의 검증된 View 계획을 현재 Report source와 연결할 수 없습니다.",
            }
        ], previous
    operations, errors = _normalize_operations(
        previous.get("operations"),
        source,
        "",
        allow_persisted_filter_values=True,
    )
    if not errors and not any(item.get("operation") == "select" for item in operations):
        previous_columns = _string_list(previous.get("output_columns"))
        source_columns = set(_string_list(source.get("columns")))
        if previous_columns and all(column in source_columns for column in previous_columns):
            operations.append({"operation": "select", "columns": previous_columns})
    return operations, errors, previous


# 함수 설명: 이전 subset 연산 뒤에 현재 delta 연산을 붙이고 projection은 맨 마지막으로 이동합니다.
def _compose_operations(previous: list[dict[str, Any]], current: list[dict[str, Any]]) -> list[dict[str, Any]]:
    previous_body = [deepcopy(item) for item in previous if item.get("operation") != "select"]
    current_body = [deepcopy(item) for item in current if item.get("operation") != "select"]
    previous_selects = [deepcopy(item) for item in previous if item.get("operation") == "select"]
    current_selects = [deepcopy(item) for item in current if item.get("operation") == "select"]
    projection = current_selects[-1:] or previous_selects[-1:]
    return [*previous_body, *current_body, *projection]


# 함수 설명: 실행을 차단하고 trace에 계약 오류를 기록한 payload를 만듭니다.
def _blocked(payload: dict[str, Any], issue: dict[str, Any], *, reason: str = "report_followup_plan_invalid") -> dict[str, Any]:
    payload.setdefault("trace", {}).setdefault("errors", []).append(deepcopy(issue))
    payload["intent_plan"] = {
        "analysis_kind": "report_followup_snapshot_transform",
        "request_scope": "report_followup",
        "reference_mode": "none",
        "reuse_strategy": "none",
        "retrieval_jobs": [],
        "report_execution_plan": {},
    }
    payload["execution_gate"] = {"status": "blocked", "reason": reason}
    payload.setdefault("analysis", {}).update({"status": "skipped", "row_count": 0, "columns": []})
    payload.setdefault("data", {}).update({"row_count": 0, "columns": [], "rows": []})
    return payload


# 주요 함수: 모델 계획을 검증해 Result Loader 호환 Report 실행 계약으로 변환합니다.
def normalize_report_followup_plan(payload_value: Any, llm_response_value: Any) -> dict[str, Any]:
    payload = _payload(payload_value)
    followup = payload.get("report_followup") if isinstance(payload.get("report_followup"), dict) else {}
    upstream_status = _text(followup.get("status"))
    if upstream_status != "ready":
        payload["intent_plan"] = {
            "analysis_kind": "report_followup_snapshot_transform",
            "request_scope": "report_followup",
            "reference_mode": "none",
            "reuse_strategy": "none",
            "retrieval_jobs": [],
            "report_execution_plan": {},
        }
        payload["execution_gate"] = {"status": upstream_status or "blocked", "reason": f"report_followup_{upstream_status or 'blocked'}"}
        return payload

    parsed = _parse_response(llm_response_value)
    if not parsed:
        return _blocked(payload, {"type": "report_followup_plan_response_invalid", "message": "Report 후속 계획 LLM 응답을 JSON object로 해석할 수 없습니다."})
    response_status = _text(parsed.get("status") or "ready").casefold()
    if response_status != "ready":
        issue = {
            "type": "report_followup_clarification_required",
            "message": _text(parsed.get("reason")) or "Report 후속 요청을 안전한 실행 계획으로 확정할 수 없습니다.",
        }
        payload.setdefault("trace", {}).setdefault("errors", []).append(issue)
        payload["intent_plan"] = {
            "analysis_kind": "report_followup_snapshot_transform",
            "request_scope": "clarification",
            "reference_mode": "none",
            "reuse_strategy": "none",
            "retrieval_jobs": [],
            "report_execution_plan": {},
        }
        payload["execution_gate"] = {"status": "clarification_required", "reason": issue["type"]}
        return payload

    sources = _sources(payload)
    candidates = set(_string_list(followup.get("candidate_source_aliases")))
    source_alias = _text(parsed.get("source_alias"))
    if not source_alias and len(candidates) == 1:
        source_alias = next(iter(candidates))
    source = sources.get(source_alias)
    if not source:
        return _blocked(payload, {"type": "report_followup_source_not_declared", "message": f"Report가 선언하지 않은 source_alias입니다: {source_alias or '(empty)'}"})
    if candidates and source_alias not in candidates:
        return _blocked(payload, {"type": "report_followup_source_not_grounded", "message": f"현재 질문에서 선택할 근거가 없는 Report View입니다: {source_alias}"})
    if source.get("contract_version") != QUERY_SOURCE_CONTRACT_VERSION or source.get("authoritative") is not True:
        return _blocked(payload, {"type": "report_followup_source_not_authoritative", "message": f"저장된 Report query source 계약을 신뢰할 수 없습니다: {source_alias}"})

    current_operations, current_errors = _normalize_operations(parsed.get("operations"), source, _normalized_question(payload))
    previous_operations, inheritance_errors, previous_plan = _inherited_operations(payload, source)
    errors = [*inheritance_errors, *current_errors]
    if errors:
        payload.setdefault("trace", {}).setdefault("errors", []).extend(errors)
        payload["execution_gate"] = {"status": "blocked", "reason": "report_followup_plan_validation_failed"}
        payload["intent_plan"] = {
            "analysis_kind": "report_followup_snapshot_transform",
            "request_scope": "report_followup",
            "reference_mode": "none",
            "reuse_strategy": "none",
            "retrieval_jobs": [],
            "report_execution_plan": {},
        }
        return payload

    operations = _compose_operations(previous_operations, current_operations)
    if len(operations) > MAX_OPERATIONS:
        return _blocked(
            payload,
            {
                "type": "report_followup_operation_limit_exceeded",
                "message": f"상속된 연산을 포함한 Report 후속 operation은 최대 {MAX_OPERATIONS}개까지 허용합니다.",
            },
            reason="report_followup_plan_validation_failed",
        )

    default_columns = _string_list(source.get("default_display_columns"))
    selected_columns = next((item["columns"] for item in reversed(operations) if item.get("operation") == "select"), [])
    output_columns = selected_columns or default_columns or _string_list(source.get("columns"))[:20]
    sort_contract = next((deepcopy(item) for item in reversed(operations) if item.get("operation") == "sort"), {})
    top_contract = next((deepcopy(item) for item in reversed(operations) if item.get("operation") == "top_n"), {})
    report_plan = {
        "contract_version": PLAN_CONTRACT_VERSION,
        "source_alias": source_alias,
        "dataset_key": _text(source.get("dataset_key")) or source_alias,
        "source_view_key": _text(source.get("purpose")) or source_alias,
        "grain": deepcopy(source.get("grain") or {}),
        "operations": operations,
        "output_columns": output_columns,
        "inherited_previous_view": bool(previous_operations or previous_plan),
        "reason": _text(parsed.get("reason"))[:500],
    }
    intent_plan = {
        "analysis_kind": "report_followup_snapshot_transform",
        "request_scope": "followup_transform",
        "reference_mode": "previous_source",
        "reuse_strategy": "previous_source",
        "retrieval_jobs": [],
        "pandas_execution_plan": [],
        "report_execution_plan": report_plan,
        "resolved_execution_graph": {
            "external_source_requirements": [
                {
                    "kind": "external_source",
                    "provider": "previous_source",
                    "source_alias": source_alias,
                    "dataset_key": report_plan["dataset_key"],
                }
            ]
        },
        "output_contract": {
            "source_alias": source_alias,
            "columns": output_columns,
            "ordering": sort_contract,
            "limit": top_contract.get("limit", 0),
        },
    }
    payload["intent_plan"] = intent_plan
    payload["execution_gate"] = {"status": "ready", "reason": "report_followup_plan_validated"}
    payload.setdefault("trace", {}).setdefault("inspection", {})["report_followup_plan"] = {
        "stage": "01_report_followup_plan_normalizer",
        "status": "ready",
        "source_alias": source_alias,
        "source_view_key": report_plan["source_view_key"],
        "operation_count": len(operations),
        "inherited_operation_count": len(previous_operations),
        "current_operation_count": len(current_operations),
        "retrieval_job_count": 0,
        "errors": [],
    }
    return payload


# Langflow 컴포넌트 클래스: 모델 응답을 안전한 Report 후속 실행 계획으로 정규화합니다.
class ReportFollowupPlanNormalizer(Component):
    display_name = "01 Report 후속 실행 계획 검증기"
    description = "LLM JSON을 Report가 선언한 물리 source·column·operation 계약으로 재검증합니다."
    name = "ReportFollowupPlanNormalizer"
    icon = "ShieldCheck"
    inputs = [
        DataInput(name="payload", display_name="Report 후속 요청 페이로드", required=True),
        MessageTextInput(name="llm_response", display_name="Report 후속 계획 LLM 응답", required=False),
    ]
    outputs = [Output(name="payload_out", display_name="검증된 실행 페이로드", method="build_payload", types=["Data"])]

    # Langflow 출력 함수: 검증과 정규화를 마친 계획 payload를 반환합니다.
    def build_payload(self) -> Data:
        result = normalize_report_followup_plan(getattr(self, "payload", None), getattr(self, "llm_response", None))
        self.status = result.get("trace", {}).get("inspection", {}).get("report_followup_plan", result.get("execution_gate", {}))
        return Data(data=result)

